    "dt.chua_co": ["Chưa có địa điểm nào. Quản trị thêm địa điểm hoặc nhập bằng file Excel mẫu.", "No places yet. The Admin can add one or import the Excel template.", "暂无地点。管理员可添加或导入Excel模板。"],
    "anh.tu_kho": ["Ảnh của cả họ", "Family photos", "家族照片"],
    "anh.kho_trong": ["Chưa có ảnh nào được duyệt. Người nhà có thể gửi ảnh, Quản trị duyệt thì hiện ở đây.", "No approved photos yet. Members can send photos; they appear here once approved.", "暂无已审核照片。成员可提交照片，审核后显示在此。"],
    "anh.xem_het_kho": ["Xem toàn bộ Kho tư liệu", "Open the whole archive", "查看全部资料库"],
    "anh.tren_may": ["Ảnh lưu trên máy này", "Photos stored on this device", "本机保存的照片"],
    "anh.luu_may": ["Ảnh thêm ở phần này chỉ lưu trên thiết bị đang dùng. Muốn cả họ cùng xem, hãy gửi ảnh qua Kho tư liệu.", "Photos added here stay on this device only. To share with the family, send them through the archive.", "此处添加的照片仅保存在本设备。如需全族共享，请通过资料库提交。"],
    "nhac.ten_lich": ["Lịch dòng họ Tống", "Tống family calendar", "宋氏家族日历"],
    "nhac.sync_tieu": ["Tự động đồng bộ lịch vào điện thoại", "Sync the calendar to your phone", "自动同步日历到手机"],
    "nhac.sync_mo_ta": ["Đăng ký lịch dòng họ một lần: ngày giỗ tự hiện trong ứng dụng Lịch của iPhone/Android và tự cập nhật, không cần mở web.", "Subscribe once: memorial days appear in your phone's Calendar and update automatically.", "订阅一次：忌日自动出现在手机日历中并自动更新。"],
    "nhac.dang_ky": ["Đăng ký lịch dòng họ", "Subscribe to family calendar", "订阅家族日历"],
    "nhac.chep_link": ["Chép link", "Copy link", "复制链接"],
    "nhac.chua_web": ["Chức năng này cần mở web từ địa chỉ trên mạng (ví dụ GitHub Pages), không dùng được khi mở file trực tiếp.", "This needs the site opened from its web address, not from a local file.", "需要通过网址打开网站，不能直接打开本地文件。"],
    "nhac.huong_dan_ios": ["Hướng dẫn cho iPhone", "iPhone guide", "iPhone 指南"],
    "nhac.i1": ["Trên iPhone mở Cài đặt → Lịch → Tài khoản → Thêm tài khoản → Khác → Thêm lịch đã đăng ký.", "On iPhone open Settings → Calendar → Accounts → Add Account → Other → Add Subscribed Calendar.", "在 iPhone 打开 设置 → 日历 → 账户 → 添加账户 → 其他 → 添加已订阅的日历。"],
    "nhac.i2": ["Dán link lịch (bấm \"Chép link\" ở trên), chọn Tiếp.", "Paste the calendar link (use “Copy link” above), tap Next.", "粘贴日历链接（点上方“复制链接”），点下一步。"],
    "nhac.i3": ["Bấm Lưu. Lịch \"Lịch dòng họ Tống\" sẽ hiện trong ứng dụng Lịch.", "Tap Save. The family calendar appears in Calendar.", "点存储，家族日历将出现在日历中。"],
    "nhac.i4": ["Cách nhanh hơn: mở trang này bằng Safari rồi bấm nút \"Đăng ký lịch dòng họ\", chọn Đăng ký.", "Faster: open this page in Safari and tap “Subscribe”, then confirm.", "更快：用 Safari 打开本页，点“订阅家族日历”并确认。"],
    "nhac.i5": ["Muốn được báo trước: Cài đặt → Lịch → Cảnh báo mặc định, hoặc vào Lịch → Lịch → ⓘ cạnh lịch dòng họ để chọn cảnh báo.", "For alerts: Settings → Calendar → Default Alerts, or Calendar → Calendars → ⓘ next to the family calendar.", "设置提醒：设置 → 日历 → 默认提醒，或日历 → 日历 → ⓘ。"],
    "nhac.i_luu_y": ["iPhone tự làm mới lịch đã đăng ký theo chu kỳ (thường vài giờ đến một ngày). Lịch chỉ gồm ngày giỗ của người được công khai.", "iPhone refreshes subscribed calendars periodically. It only contains public memorial days.", "iPhone 会定期刷新订阅日历。仅包含公开的忌日。"],
    "nhac.huong_dan_and": ["Hướng dẫn cho Android", "Android guide", "Android 指南"],
    "nhac.a1": ["Bấm \"Đăng ký lịch dòng họ\" ở trên hoặc mở Google Calendar trên máy tính → Lịch khác → Từ URL.", "Tap “Subscribe” above, or in Google Calendar on a computer → Other calendars → From URL.", "点上方“订阅”，或在电脑 Google 日历 → 其他日历 → 通过网址。"],
    "nhac.a2": ["Dán link lịch rồi Thêm lịch.", "Paste the link and add.", "粘贴链接并添加。"],
    "nhac.a3": ["Lịch tự đồng bộ sang điện thoại đăng nhập cùng tài khoản Google.", "It syncs to phones signed in with the same Google account.", "会同步到登录同一 Google 账号的手机。"],
    "nhac.quan_tri": ["Dành cho Quản trị: tạo file lịch", "Admin: create the calendar file", "管理员：生成日历文件"],
    "nhac.qt_mo_ta": ["Bấm nút dưới để tạo file lich-ho-tong.ics (ngày giỗ 3 năm tới của người được công khai), rồi tải file lên GitHub cùng thư mục với index.html, giữ nguyên tên. Mỗi khi sửa ngày giỗ, tạo lại và tải lên; điện thoại sẽ tự cập nhật.", "Create lich-ho-tong.ics (public memorial days for 3 years) and upload it next to index.html with the same name. Recreate it after editing dates.", "生成 lich-ho-tong.ics（未来3年公开忌日），上传到 index.html 同一目录，名称不变。修改日期后需重新生成。"],
    "nhac.tao_file": ["Tạo file lịch dòng họ", "Create calendar file", "生成日历文件"],
    "nhac.da_tao": ["Đã tạo file lịch", "Calendar file created", "已生成日历文件"],
    "nhac.da_chep": ["Đã chép link", "Link copied", "已复制链接"],
    "nhac.file_co": ["✓ Đã tìm thấy file lịch trên web.", "✓ Calendar file found on the site.", "✓ 网站上已找到日历文件。"],
    "nhac.file_chua": ["Chưa thấy file lich-ho-tong.ics trên web: nhờ Quản trị tạo và tải lên.", "lich-ho-tong.ics not found: ask the Admin to create and upload it.", "未找到 lich-ho-tong.ics：请管理员生成并上传。"],
