    "map.sua_vi_tri": ["Sửa vị trí", "Edit location", "修改位置"], "map.them_noi": ["Thêm nơi an táng mới", "Add a burial place", "添加安葬地点"], "map.vd_ten": ["VD: Khu mộ tổ chi 2 – nghĩa trang làng", "e.g. Branch 2 family tomb – village cemetery", "例：二房祖坟"],
    "map.chua_vi_tri": ["Chưa có vị trí cố định cho nơi này. Hãy nhập địa chỉ hoặc dán link Google Maps để bản đồ hiện đúng chỗ.", "No fixed location yet. Enter an address or paste a Google Maps link so the map shows the exact place.", "尚无固定位置。请输入地址或粘贴谷歌地图链接。"], "map.chua_vi_tri_ngan": ["Chưa có địa chỉ / vị trí", "No address / location yet", "尚无地址/位置"],
    "map.loc_chinh_xac": ["Đúng điểm đã ghim trên Google Maps", "Exact pin from Google Maps", "谷歌地图上已标记的准确位置"], "map.loc_theo_dc": ["Theo địa chỉ đã nhập (Google tự tìm). Dán link Google Maps để ghim chính xác hơn.", "From the typed address (Google searches). Paste a Google Maps link for an exact pin.", "按所填地址（由谷歌查找）。粘贴谷歌地图链接可更精确。"],
    "kin.qu_trung": ["Miền Trung (Ba/Bọ, Mạ, Mệ, O, Dì…)", "Central Vietnam (Ba/Bọ, Mạ, Mệ, O, Dì…)", "中部（Ba/Bọ、Mạ、Mệ、O、Dì…）"], "kin.qua": ["Liên hệ qua hôn nhân, thông qua", "Related by marriage, through", "通过婚姻关系，经由"],
    "note.vung_trung": ["Miền Trung (tuỳ địa phương): cha gọi Ba/Bọ; mẹ gọi Mạ/Má (Huế, Quảng) hoặc Mự (Nghệ Tĩnh); bà gọi Mệ (Huế); chị/em gái của cha gọi O (Huế) hoặc Cô; chị/em gái của mẹ gọi Dì, chồng của O/Dì gọi Dượng.", "Central Vietnam (varies locally): father Ba/Bọ; mother Mạ/Má or Mự; grandmother Mệ (Huế); father's sister O or Cô; mother's sister Dì; her husband Dượng.", "中部（因地而异）：父称 Ba/Bọ；母称 Mạ/Má 或 Mự；祖母称 Mệ（顺化）；姑称 O 或 Cô；姨称 Dì，其夫称 Dượng。"],
    "note.gt_theo_chong": ["Họ hàng bên chồng: với bố mẹ và anh chị em chồng có cách gọi riêng; còn lại thường gọi theo cách của chồng.", "In-laws on the husband's side: parents and siblings have their own terms; others are usually called as the husband calls them.", "夫家亲属：公婆与小叔姑有专称；其余多随丈夫称呼。"],
    "note.gt_theo_vo": ["Họ hàng bên vợ: với bố mẹ và anh chị em vợ có cách gọi riêng; còn lại thường gọi theo cách của vợ.", "In-laws on the wife's side: parents and siblings have their own terms; others are usually called as the wife calls them.", "妻家亲属：岳父母与妻兄弟姐妹有专称；其余多随妻子称呼。"],
    "note.gt_qua_ho_hang": ["Gọi theo vợ/chồng của người họ hàng ruột.", "Named after the blood relative's spouse.", "按血亲配偶称呼。"], "note.dong_hao": ["Chồng của hai chị em ruột gọi nhau là anh em đồng hao (còn gọi cột chèo).", "Husbands of two sisters call each other đồng hao (cột chèo).", "姐妹的丈夫互称 đồng hao（连襟）。"],
    "note.chi_em_dau": ["Vợ của hai anh em ruột gọi nhau là chị em dâu.", "Wives of two brothers call each other chị em dâu.", "兄弟的妻子互称 chị em dâu（妯娌）。"], "note.thong_gia": ["Hai bên gia đình có con cái kết hôn gọi nhau là thông gia (miền Nam, Trung hay nói sui gia).", "Families joined by a marriage are thông gia (sui gia in South/Central).", "儿女联姻的两家互称 thông gia（亲家）。"],
