    "map.chua_co_td": ["Chưa có địa điểm nào có tọa độ.", "No place has coordinates yet.", "尚无带坐标的地点。"], "map.so_do_alt": ["Sơ đồ vị trí tương đối giữa các địa điểm", "Relative position diagram of places", "地点相对位置示意图"],
    "map.ghi_chu_so_do": ["Đây là sơ đồ vị trí tương đối từ tọa độ (Bắc ở phía trên), không phải bản đồ nền. Bấm “Chỉ đường” hoặc “Mở Google Maps” để xem bản đồ thật.", "A relative-position diagram drawn from coordinates (north up), not a base map. Use “Directions” or “Open Google Maps” for the real map.", "这是根据坐标绘制的相对位置示意图（上为北），不是底图。请点“导航”或“打开谷歌地图”查看真实地图。"],
    "map.chon_diem": ["Bấm một điểm trên sơ đồ hoặc trong danh sách để xem chi tiết.", "Tap a pin or list item for details.", "点击地图上的点或列表项查看详情。"], "map.chi_duong": ["Chỉ đường", "Directions", "导航"], "map.mo_gg": ["Mở Google Maps", "Open Google Maps", "打开谷歌地图"],
    "map.toa_do": ["Tọa độ", "Coordinates", "坐标"], "map.chep_link": ["Chép link", "Copy link", "复制链接"], "map.do_chinh_xac": ["Độ chính xác tọa độ", "Coordinate accuracy", "坐标可信度"], "map.td_chua_chac": ["Nên ra tận nơi ghim lại bằng GPS để chắc chắn.", "Best to pin it on site with GPS to be sure.", "建议到现场用 GPS 定位确认。"],
    "map.thieu_td": ["Địa điểm này chưa có tọa độ nên chưa chỉ đường được. Quản trị có thể bổ sung.", "This place has no coordinates yet, so directions are unavailable. An admin can add them.", "此地点尚无坐标，暂无法导航。管理员可补充。"], "map.tim_theo_dia_chi": ["Thử tìm theo địa chỉ trên Google Maps", "Try searching by address on Google Maps", "试在谷歌地图按地址搜索"],
    "map.khoang_cach": ["Khoảng cách đến các nơi khác", "Distance to other places", "到其他地点的距离"], "map.chim_bay": ["Đường chim bay; quãng đường đi thực tế sẽ dài hơn, hãy xem trong Google Maps.", "Straight-line distance; actual driving distance is longer — check Google Maps.", "直线距离；实际行车距离更长，请在谷歌地图查看。"],
    "map.sua_td": ["Sửa tọa độ và chỉ dẫn", "Edit coordinates and directions", "编辑坐标与说明"], "map.dan_toa_do": ["Dán tọa độ hoặc link Google Maps", "Paste coordinates or a Google Maps link", "粘贴坐标或谷歌地图链接"],
    "map.cach_lay": ["Cách lấy: mở Google Maps, bấm giữ vào đúng chỗ cần ghim, tọa độ hiện ở đầu ô tìm kiếm (hoặc chọn “Chia sẻ” rồi dán link đầy đủ). Link rút gọn dạng maps.app.goo.gl chưa đọc được — hãy mở link ra rồi chép tọa độ.", "How: in Google Maps, long-press the exact spot; coordinates appear in the search box (or Share and paste the full link). Short maps.app.goo.gl links cannot be read — open it and copy the coordinates.", "方法：在谷歌地图长按准确位置，坐标会显示在搜索框（或分享后粘贴完整链接）。maps.app.goo.gl 短链无法解析，请打开后复制坐标。"],
    "map.td_sai": ["Chưa đọc được tọa độ. Hãy dán dạng “21.0285, 105.8542”.", "Cannot read the coordinates. Use the form “21.0285, 105.8542”.", "无法识别坐标，请使用“21.0285, 105.8542”格式。"], "map.ngoai_vn": ["Tọa độ nằm ngoài Việt Nam — bạn kiểm tra lại giúp.", "Coordinates are outside Vietnam — please double-check.", "坐标在越南境外，请再核对。"],
